import React, { useState, useEffect } from 'react';
import ModalForm from '../../components/ModalForm';

function ProductsList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [showModal, setShowModal] = useState(false);

  const token = localStorage.getItem('token');

  const fetchProducts = async () => {
    try {
      const res = await fetch('http://localhost/api/productes', {
        headers: { Authorization: `Bearer ${token}` }
      });
      const data = await res.json();
      setProducts(data.dades || []);
    } catch (err) {
      setError('Error al obtenir els productes');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchProducts(); }, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Segur que vols eliminar aquest producte?')) return;
    try {
      const res = await fetch(`http://localhost/api/productes/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) throw new Error('Error al eliminar');
      setProducts(products.filter(p => p.id !== id));
    } catch (err) {
      alert(err.message);
    }
  };

  const handleEdit = (product) => {
    setSelectedProduct(product);
    setShowModal(true);
  };

  if (loading) return <p>Carregant productes...</p>;
  if (error) return <p>{error}</p>;
  if (products.length === 0) return <p>No hi ha productes disponibles.</p>;

  return (
    <div>
      <button className="btn btn-success mb-3" onClick={() => { setSelectedProduct(null); setShowModal(true); }}>
        Crear Producte
      </button>

      <div className="row">
        {products.map(product => (
          <div key={product.id} className="col-md-4 mb-3">
            <div className="card h-100">
              <div className="card-body">
                <h5 className="card-title">{product.nom}</h5>
                <p className="card-text">{product.descripcio}</p>
                <p className="card-text"><strong>Referència:</strong> {product.referencia}</p>
                <p className="card-text"><strong>Quantitat:</strong> {product.quantitat}</p>
                <button className="btn btn-primary me-2" onClick={() => handleEdit(product)}>Editar</button>
                <button className="btn btn-danger" onClick={() => handleDelete(product.id)}>Eliminar</button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <ModalForm
          entity="productes"
          data={selectedProduct}
          onClose={() => { setShowModal(false); fetchProducts(); }}
        />
      )}
    </div>
  );
}

export default ProductsList;
